# Major investor markets that get their own page under /locations/<state>/<metro>/ (only when the state is served).
# 'angle' is the market-specific paragraph. Keep it qualitative and true; never invent statistics.
$Metros = @(
  @{ slug="atlanta"; name="Atlanta"; abbr="GA"; programs="rental and renovation"; angle="Metro Atlanta is one of the most active investor markets in the Southeast, with a deep supply of single-family homes in the surrounding suburbs and a steady flow of renovation projects inside the perimeter. Investors here use short-term loans to buy and renovate, then refinance the finished properties into long-term rental financing." }
  @{ slug="tampa"; name="Tampa"; abbr="FL"; programs="rental and renovation"; angle="The Tampa Bay area combines strong rental demand with older housing stock that rewards renovation. Insurance and flood-zone considerations vary a lot by neighborhood and can change how a rental pencils out, so running the full payment early matters." }
  @{ slug="orlando"; name="Orlando"; abbr="FL"; programs="rental and short-term rental"; angle="Orlando's tourism-driven economy supports both traditional rentals and short-term rental strategies, and its steady growth keeps renovation and new construction active. Always confirm local short-term rental rules before you underwrite a deal around them." }
